using System;
using System.Collections.Generic;
using System.Linq;
using System.ServiceModel;
using System.Text;
using System.Text.RegularExpressions;
using System.Runtime.Remoting.Proxies;
using System.Runtime.Remoting.Messaging;
using System.Web.Script.Serialization;
using System.Xml.Linq;
using Microsoft.Xrm.Sdk;
using Microsoft.Xrm.Sdk.Query;
using Oiac.Engage.ContactDirectory;

public static class ContactDirectoryTests {
 static readonly Guid Actor=Guid.Parse("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"), Other=Guid.Parse("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"), User=Guid.Parse("cccccccc-cccc-cccc-cccc-cccccccccccc"), D1=Guid.Parse("11111111-1111-1111-1111-111111111111"), D2=Guid.Parse("22222222-2222-2222-2222-222222222222"), D3=Guid.Parse("33333333-3333-3333-3333-333333333333");
 static readonly JavaScriptSerializer Serializer=new JavaScriptSerializer();
 static int passed,failed;
 static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 static Dictionary<string,object> Parse(string value){return (Dictionary<string,object>)Serializer.DeserializeObject(value);}
 static Dictionary<string,object> Call(Fake db,Guid? actor=null,string search="",int page=1,string cookie=""){return Parse(ContactDirectoryPlugin.Run(db,actor??Actor,search,page,cookie));}
 static Dictionary<string,object>[] Rows(Dictionary<string,object> result){Assert(result.ContainsKey("ok")&&(bool)result["ok"],Serializer.Serialize(result));return ((object[])result["contacts"]).Cast<Dictionary<string,object>>().ToArray();}
 static void Code(Dictionary<string,object> result,string code){Assert(!(bool)result["ok"],"unexpected success");Assert((string)((Dictionary<string,object>)result["error"])["code"]==code,Serializer.Serialize(result));}
 static string Token(object cursor){return Convert.ToBase64String(Encoding.UTF8.GetBytes(Serializer.Serialize(cursor))).TrimEnd('=').Replace('+','-').Replace('/','_');}
 static Dictionary<string,object> Cursor(string token){return Parse(Encoding.UTF8.GetString(Convert.FromBase64String(token.Replace('-','+').Replace('_','/').PadRight((token.Length+3)/4*4,'='))));}
 static Dictionary<string,string> Next(Dictionary<string,object> result){var url=(string)result["nextLink"];Assert(url!=null&&url.StartsWith("/_api/serverlogics/contact-directory?"),"next route");return url.Substring(url.IndexOf('?')+1).Split('&').Select(p=>p.Split(new[]{'='},2)).ToDictionary(p=>p[0],p=>Uri.UnescapeDataString(p[1]));}
 static Guid Add(Fake db,string name,params Guid[] districts){var id=Guid.NewGuid();var row=Contact(id,name);db.Contacts.Add(row);foreach(var d in districts)db.Memberships.Add(Membership(id,d));return id;}
 static Entity Contact(Guid id,string name){var e=new Entity("contact",id);e["contactid"]=id;e["fullname"]=name;e["statecode"]=new OptionSetValue(0);return e;}
 static Entity Membership(Guid contact,Guid district,int state=0){var e=new Entity("mss_contactdistrictmembership",Guid.NewGuid());e["mss_contact"]=new EntityReference("contact",contact);e["mss_district"]=new EntityReference("mss_district",district);e["statecode"]=new OptionSetValue(state);return e;}
 static Fake Seed(){var db=new Fake();db.Contacts.Add(Contact(Actor,"Actor"));db.Contacts.Add(Contact(Other,"Other actor"));return db;}
 public static int Main(){
 Test("one district limits contacts to shared active memberships",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));Guid included=Add(db,"Included",D1),excluded=Add(db,"Excluded",D2);var rows=Rows(Call(db));Assert(rows.Any(r=>(string)r["contactid"]==included.ToString()),"missing shared contact");Assert(!rows.Any(r=>(string)r["contactid"]==excluded.ToString()),"cross district leak");});
 Test("multi district union returns one contact for overlapping and duplicate memberships",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));db.Memberships.Add(Membership(Actor,D2));db.Memberships.Add(Membership(Actor,D1));Guid a=Add(db,"North",D1),b=Add(db,"South",D2),both=Add(db,"Both",D1,D2,D1);Add(db,"Outside",D3);var rows=Rows(Call(db));foreach(Guid id in new[]{a,b,both})Assert(rows.Count(r=>(string)r["contactid"]==id.ToString())==1,"missing or duplicated union contact");Assert(rows.Length==4,"unexpected union size (includes actor)");});
 Test("inactive actor membership cannot authorize a district",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1,1));Add(db,"Hidden",D1);Assert(Rows(Call(db)).Length==0,"inactive assignment leaked");});
 Test("inactive target membership and contact are excluded",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));Guid inactive=Add(db,"Inactive contact",D1);db.Contacts.First(e=>e.Id==inactive)["statecode"]=new OptionSetValue(1);Guid inactiveLink=Add(db,"Inactive membership");db.Memberships.Add(Membership(inactiveLink,D1,1));Assert(Rows(Call(db)).Length==1,"inactive rows included");});
 Test("unassigned actor sees an empty directory",()=>{var db=Seed();Add(db,"Public active",D1);Assert(Rows(Call(db)).Length==0,"unassigned actor leaked directory");});
 Test("active actor does not need portal identity fields",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));Assert(Rows(Call(db)).Length==1,"identity fields required");});
 Test("inactive missing or anonymous actor cannot query contacts",()=>{foreach(int mode in new[]{0,1,2}){var db=Seed();if(mode==0)db.Contacts.First(e=>e.Id==Actor)["statecode"]=new OptionSetValue(1);if(mode==1)db.Contacts.RemoveAll(e=>e.Id==Actor);Code(Call(db,mode==2?Guid.Empty:Actor),mode==2?"unauthenticated":"forbidden");Assert(db.Fetches.Count==0,"queried denied actor");}});
 foreach(string field in new[]{"fullname","emailaddress1","mobilephone","address1_city"}){string f=field;Test("literal case insensitive partial search in "+f,()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));Guid good=Add(db,"Literal",D1),bad=Add(db,"Distractor",D1);db.Contacts.First(e=>e.Id==good)[f]="Prefix A%_[]<&\"'Z suffix";db.Contacts.First(e=>e.Id==bad)[f]="Prefix AxxZ suffix";var rows=Rows(Call(db,search:"a%_[]<&\"'z"));Assert(rows.Length==1&&(string)rows[0]["contactid"]==good.ToString(),"literal search mismatch");});}
 Test("server filtering finds contacts after six hundred nonmatches",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<600;i++)Add(db,"Earlier "+i,D1);Guid target=Add(db,"Zulu target",D1);Assert((string)Rows(Call(db,search:"target"))[0]["contactid"]==target.ToString(),"filtered after page limit");Assert(db.Fetches.Count==1,"client-side scan");});
 Test("projection emits only approved OData fields and formatted district",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));Guid id=Add(db,"Visible",D1);var row=db.Contacts.First(e=>e.Id==id);row["emailaddress1"]="v@example.test";row["mobilephone"]="123";row["address1_city"]="Town";row["mss_district"]=new EntityReference("mss_district",D2);row.FormattedValues["mss_district"]="Legacy label";row["adx_identity_passwordhash"]="SECRET";var rows=Rows(Call(db,search:"Visible"));var r=rows.Single();Assert(r.Count==7,"wrong projection");Assert((string)r["_mss_district_value"]==D2.ToString(),"lookup shape");Assert((string)r["_mss_district_value@OData.Community.Display.V1.FormattedValue"]=="Legacy label","formatted lookup");Assert(!Serializer.Serialize(r).Contains("SECRET"),"secret projected");var xml=db.Fetches.Single();Assert(xml.Element("entity").Elements("attribute").Count()==6,"SDK overfetch");});
 Test("missing optional fields remain null and no invented district label",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));var row=Rows(Call(db)).Single();Assert(row.Count==6&&row["emailaddress1"]==null&&row["_mss_district_value"]==null,"missing field shape");});
 Test("result order uses fullname then contactid for equal names",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));var id1=Guid.Parse("00000001-0000-0000-0000-000000000000");var id2=Guid.Parse("00000002-0000-0000-0000-000000000000");var id3=Guid.Parse("00000003-0000-0000-0000-000000000000");db.Contacts.Add(Contact(id3,"Sort A"));db.Contacts.Add(Contact(id2,"Sort Z"));db.Contacts.Add(Contact(id1,"Sort A"));foreach(var id in new[]{id1,id2,id3})db.Memberships.Add(Membership(id,D1));var rows=Rows(Call(db,search:"Sort"));Assert(rows.Select(r=>(string)r["contactid"]).SequenceEqual(new[]{id1.ToString(),id3.ToString(),id2.ToString()}),"unstable ordering");});
 Test("601 contacts page through native XML cookies with deterministic fullname/id ordering",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<601;i++)Add(db,"Member "+(i/2).ToString("D4"),D1,D1);var ids=new HashSet<string>();string cookie="";int page=1;while(true){var result=Call(db,search:"Member",page:page,cookie:cookie);var rows=Rows(result);Assert(rows.Length<=15,"unbounded page");foreach(var row in rows)Assert(ids.Add((string)row["contactid"]),"duplicate contact");if(result["nextLink"]==null)break;var next=Next(result);Assert(next["q"]=="Member"&&next["page"]==(page+1).ToString(),"next context");cookie=next["cookie"];Assert(Regex.IsMatch(cookie,"^[A-Za-z0-9_-]+$"),"unsafe token");page++;Assert(page<50,"paging loop");}Assert(ids.Count==601&&page==41&&db.Fetches.Count==41,"lost contacts/pages");Assert(db.Cookies.Skip(1).All(c=>c!=null&&c.Contains("O&apos;Neil منى")),"native XML cookie did not roundtrip");});
 Test("continuation binds actor search and expected page",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<16;i++)Add(db,"Member "+i,D1);var next=Next(Call(db,search:"Member"));string token=next["cookie"];int calls=db.Fetches.Count;Code(Call(db,Other,"Member",2,token),"validation");Code(Call(db,Actor,"Other",2,token),"validation");Code(Call(db,Actor,"Member",3,token),"validation");Code(Call(db,Actor,"Member",1,token),"validation");Assert(db.Fetches.Count==calls,"mismatched continuation queried");Assert(Rows(Call(db,Actor,"Member",2,token)).Length==1,"valid continuation denied");});
 Test("escaped search survives URL and cursor without normalization",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<16;i++)Add(db," A+B & منى "+i,D1);string term=" A+B & منى ";var next=Next(Call(db,search:term));Assert(next["q"]==term,"search changed");var c=Cursor(next["cookie"]);Assert((string)c["search"]==term,"cursor search changed");Assert(Rows(Call(db,search:term,page:2,cookie:next["cookie"])).Length==1,"URL continuation");});
 foreach(string token in new[]{"a","bad!","_w",Token(new{actor=Actor.ToString(),search="",page=2,cookie=""}),Token(new{actor=Actor.ToString(),search="",page=2,cookie="native",extra=true}),Token(new{actor=Actor.ToString(),search="",page="2",cookie="native"}),Token(new{actor=Actor.ToString(),search="",page=2.5,cookie="native"}),Token(new[]{"invalid"})}){string t=token;Test("malformed cursor rejected "+t.Substring(0,Math.Min(12,t.Length)),()=>{var db=Seed();Code(Call(db,page:2,cookie:t),"validation");Assert(db.Fetches.Count==0,"bad cursor queried");});}
 Test("duplicate cursor keys are rejected",()=>{string raw="{\"actor\":\""+Actor+"\",\"search\":\"\",\"page\":2,\"page\":3,\"cookie\":\"native\"}";string t=Convert.ToBase64String(Encoding.UTF8.GetBytes(raw)).TrimEnd('=').Replace('+','-').Replace('/','_');Code(Call(Seed(),page:2,cookie:t),"validation");});
 Test("input bounds reject before retrieval",()=>{foreach(var run in new Func<Fake,Dictionary<string,object>>[]{d=>Call(d,search:new string('x',201)),d=>Call(d,search:"bad\0"),d=>Call(d,page:0),d=>Call(d,page:100001),d=>Call(d,page:2),d=>Call(d,cookie:new string('A',16385))}){var db=Seed();Code(run(db),"validation");Assert(db.Retrieves==0&&db.Fetches.Count==0,"invalid request touched SDK");}});
 Test("search length 200 and null optional values accepted",()=>{Rows(Call(Seed(),search:new string('x',200)));Rows(Call(Seed(),search:null,cookie:null));});
 Test("native faults and unexpected failures expose safe unavailable only",()=>{foreach(bool fault in new[]{false,true}){var db=Seed();db.Failure=fault?(Exception)new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{Message="SECRET SQL / credential",ErrorCode=-1}):new Exception("SECRET SQL / credential");var result=Call(db);Code(result,"unavailable");Assert(!Serializer.Serialize(result).Contains("SECRET"),"fault details leaked");}});
 Test("missing SDK continuation cookie fails closed",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<16;i++)Add(db,"Member "+i,D1);db.OmitCookie=true;Code(Call(db,search:"Member"),"unavailable");});
 Test("untransportable native continuation fails closed",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));for(int i=0;i<16;i++)Add(db,"Member "+i,D1);db.CustomCookie=new string('x',16384);Code(Call(db,search:"Member"),"unavailable");});
 Test("last allowed page cannot issue an invalid next page",()=>{var db=Seed();db.ForceMore=true;var token=Token(new{actor=Actor.ToString(),search="",page=100000,cookie=Fake.NativeCookie(99999,1499985)});Code(Call(db,page:100000,cookie:token),"unavailable");});
 Test("Execute uses caller UserId and trusted Guid actor with read calls only",()=>{var db=Seed();db.Memberships.Add(Membership(Actor,D1));var p=new Provider(db,Actor);new ContactDirectoryPlugin().Execute(p);Assert(p.FactoryUser==User,"caller impersonation lost");Assert(Rows(Parse((string)p.Output["Result"])).Length==1,"Execute result");Assert(db.Writes==0&&db.Retrieves==1&&db.Fetches.Count==1,"unexpected SDK operations");});
 Test("Execute rejects string actor and wrong typed request parameters safely",()=>{foreach(string param in new[]{"ActorContactId","Search","Page","Cookie"}){var db=Seed();var p=new Provider(db,Actor);p.Input[param]=param=="ActorContactId"?(object)Actor.ToString():param=="Page"?(object)"1":123;new ContactDirectoryPlugin().Execute(p);Code(Parse((string)p.Output["Result"]),param=="ActorContactId"?"unauthenticated":"validation");Assert(db.Fetches.Count==0,"typed input queried");}});
 Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;
 }

 // SDK is the only external boundary. This evaluator consumes the emitted FetchXML:
 // joins multiply root rows for INNER, EXISTS retains a single root, and filters run
 // before ordering/projection/native-cookie paging. It deliberately does not infer
 // the actor or expected membership relation from test fixtures.
 sealed class Fake:IOrganizationService {
  public List<Entity> Contacts=new List<Entity>(),Memberships=new List<Entity>();public List<XElement> Fetches=new List<XElement>();public List<string> Cookies=new List<string>();public int Retrieves,Writes;public Exception Failure;public bool OmitCookie,ForceMore;public string CustomCookie;
  Dictionary<XElement,Dictionary<object,List<Entity>>> joinIndexes=new Dictionary<XElement,Dictionary<object,List<Entity>>>();
  public Entity Retrieve(string name,Guid id,ColumnSet columns){Retrieves++;if(Failure!=null)throw Failure;Assert(name=="contact"&&!columns.AllColumns&&columns.Columns.SequenceEqual(new[]{"statecode"}),"actor overfetch");var row=Contacts.FirstOrDefault(r=>r.Id==id);if(row==null)throw new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{ErrorCode=-2147220969,Message="SECRET missing actor"});return Project(row,columns.Columns);}
  public EntityCollection RetrieveMultiple(QueryBase query){if(Failure!=null)throw Failure;Assert(query is FetchExpression,"native FetchExpression required");var fetch=XElement.Parse(((FetchExpression)query).Query);Fetches.Add(fetch);var root=fetch.Element("entity");Assert((string)root.Attribute("name")=="contact","wrong root");int page=(int)fetch.Attribute("page"),count=(int)fetch.Attribute("count");Assert(count==15,"page size");string cookie=(string)fetch.Attribute("paging-cookie");Cookies.Add(cookie);int start=0;if(page>1){Assert(cookie!=null,"native cookie missing");var c=XElement.Parse(cookie);Assert((int)c.Attribute("page")==page-1,"cookie/page mismatch");start=(int)c.Attribute("offset");}else Assert(cookie==null,"first page cookie");
   joinIndexes.Clear();var rows=new List<Entity>();foreach(var row in Contacts){if(!Filters(root,row))continue;int repeats=Links(root,row);for(int i=0;i<repeats;i++)rows.Add(row);}if((string)fetch.Attribute("distinct")=="true")rows=rows.GroupBy(r=>r.Id).Select(g=>g.First()).ToList();
   IOrderedEnumerable<Entity> ordered=null;foreach(var order in root.Elements("order")){string field=(string)order.Attribute("attribute");Assert((string)order.Attribute("descending")!="true","unexpected descending");ordered=ordered==null?rows.OrderBy(r=>Convert.ToString(Value(r,field)),StringComparer.OrdinalIgnoreCase):ordered.ThenBy(r=>Convert.ToString(Value(r,field)),StringComparer.OrdinalIgnoreCase);}Assert(ordered!=null,"unordered directory");rows=ordered.ToList();var attrs=root.Elements("attribute").Select(a=>(string)a.Attribute("name")).ToArray();Assert(attrs.OrderBy(x=>x).SequenceEqual(new[]{"contactid","fullname","emailaddress1","mobilephone","address1_city","mss_district"}.OrderBy(x=>x)),"contact overfetch");
   return new EntityCollection(rows.Skip(start).Take(count).Select(r=>Project(r,attrs)).ToList()){MoreRecords=ForceMore||rows.Count>start+count,PagingCookie=OmitCookie?null:CustomCookie??NativeCookie(page,start+count)};
  }
  public static string NativeCookie(int page,int offset){return "<cookie page=\""+page+"\" offset=\""+offset+"\"><fullname last=\"O&apos;Neil منى\" first=\"A &amp; B\" /></cookie>";}
  int Links(XElement parent,Entity row){int total=1;foreach(var link in parent.Elements("link-entity")){string table=(string)link.Attribute("name"),from=(string)link.Attribute("from"),to=(string)link.Attribute("to");Assert(table=="mss_contactdistrictmembership","unexpected linked table");Dictionary<object,List<Entity>> index;if(!joinIndexes.TryGetValue(link,out index)){index=Memberships.Where(e=>Value(e,from)!=null&&Filters(link,e)).GroupBy(e=>Value(e,from)).ToDictionary(g=>g.Key,g=>g.ToList());joinIndexes.Add(link,index);}int matches=0;List<Entity> candidates;object key=Value(row,to);if(key!=null&&index.TryGetValue(key,out candidates))foreach(var child in candidates)matches+=Links(link,child);total*=((string)link.Attribute("link-type")=="exists"?(matches>0?1:0):matches);}return total;}
  static bool Filters(XElement element,Entity row){return element.Elements("filter").All(f=>Filter(f,row));}
  static bool Filter(XElement f,Entity row){var results=f.Elements().Select(n=>n.Name.LocalName=="filter"?Filter(n,row):Condition(n,row));return (string)f.Attribute("type")=="or"?results.Any(x=>x):results.All(x=>x);}
  static bool Condition(XElement c,Entity row){Assert(c.Name.LocalName=="condition","unexpected filter child");object value=Value(row,(string)c.Attribute("attribute"));string op=(string)c.Attribute("operator"),wanted=(string)c.Attribute("value");if(op=="eq")return value!=null&&string.Equals(Convert.ToString(value),wanted,StringComparison.OrdinalIgnoreCase);if(op=="like"){if(value==null)return false;string regex="^";for(int i=0;i<wanted.Length;i++){if(i+2<wanted.Length&&wanted[i]=='['&&wanted[i+2]==']'){regex+=Regex.Escape(wanted[i+1].ToString());i+=2;}else regex+=wanted[i]=='%'?".*":wanted[i]=='_'?".":Regex.Escape(wanted[i].ToString());}return Regex.IsMatch(Convert.ToString(value),regex+"$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.Singleline);}throw new Exception("unsupported operator "+op);}
  static object Value(Entity row,string key){object v;if(!row.Attributes.TryGetValue(key,out v))return null;return v is EntityReference?(object)((EntityReference)v).Id:v is OptionSetValue?(object)((OptionSetValue)v).Value:v;}
  static Entity Project(Entity row,IEnumerable<string> columns){var copy=new Entity(row.LogicalName,row.Id);foreach(string field in columns){if(row.Contains(field))copy[field]=row[field];if(row.FormattedValues.Contains(field))copy.FormattedValues[field]=row.FormattedValues[field];}return copy;}
  public Guid Create(Entity e){Writes++;throw new Exception("write forbidden");}public void Update(Entity e){Writes++;throw new Exception("write forbidden");}public void Delete(string name,Guid id){Writes++;throw new Exception("write forbidden");}public OrganizationResponse Execute(OrganizationRequest r){Writes++;throw new Exception("execute forbidden");}public void Associate(string n,Guid id,Relationship r,EntityReferenceCollection e){Writes++;throw new Exception("associate forbidden");}public void Disassociate(string n,Guid id,Relationship r,EntityReferenceCollection e){Writes++;throw new Exception("disassociate forbidden");}
 }
 sealed class Provider:IServiceProvider,IOrganizationServiceFactory {
  Fake db;IPluginExecutionContext context;public Guid? FactoryUser;public ParameterCollection Input=new ParameterCollection(),Output=new ParameterCollection();
  public Provider(Fake service,object actor){db=service;Input["ActorContactId"]=actor;Input["Search"]="";Input["Page"]=1;Input["Cookie"]="";context=(IPluginExecutionContext)new ContextProxy(Input,Output).GetTransparentProxy();}
  public object GetService(Type t){return t==typeof(IPluginExecutionContext)?(object)context:t==typeof(IOrganizationServiceFactory)?this:null;}
  public IOrganizationService CreateOrganizationService(Guid? user){FactoryUser=user;return db;}
 }
 sealed class ContextProxy:RealProxy {
  ParameterCollection input,output;public ContextProxy(ParameterCollection i,ParameterCollection o):base(typeof(IPluginExecutionContext)){input=i;output=o;}
  public override IMessage Invoke(IMessage m){var call=(IMethodCallMessage)m;object v=call.MethodName=="get_MessageName"?(object)"mss_ContactDistrictDirectory":call.MethodName=="get_UserId"?User:call.MethodName=="get_InputParameters"?(object)input:call.MethodName=="get_OutputParameters"?(object)output:null;return new ReturnMessage(v,null,0,call.LogicalCallContext,call);}
 }
}
